// src/services/job.service.ts
async function searchJobs(userId, p2) {
  const t0 = Date.now();
  const page = Math.max(1, Number(p2.page ?? 1));
  const pageSize = Math.min(100, Math.max(1, Number(p2.page_size ?? 20)));
  const signals = await profileSignals(userId);
  const where = ["user_id = ?"];
  const args = [userId];
  where.push("status = 'open'");
  if (p2.category) {
    where.push("career_category = ?");
    args.push(p2.category);
  }
  if (p2.remote === true || p2.remote === "true") where.push("remote = 1");
  if (p2.seniority) {
    where.push("seniority = ?");
    args.push(p2.seniority);
  }
  if (p2.source?.length) {
    where.push(`source IN (${p2.source.map(() => "?").join(",")})`);
    args.push(...p2.source);
  }
  if (p2.salary_min) {
    where.push("(salary_max IS NULL OR salary_max >= ?)");
    args.push(Number(p2.salary_min));
  }
  if (p2.location) {
    where.push("(location IS NULL OR lower(location) LIKE ?)");
    args.push(`%${p2.location.toLowerCase()}%`);
  }
  if (p2.posted_within) {
    where.push("posted_at >= ?");
    args.push(new Date(Date.now() - Number(p2.posted_within) * 864e5).toISOString());
  }
  if (p2.q) {
    where.push("(lower(title) LIKE ? OR lower(description) LIKE ? OR lower(company_name) LIKE ? OR lower(jd_keywords) LIKE ?)");
    const like = `%${p2.q.toLowerCase()}%`;
    args.push(like, like, like, like);
  }
  if (p2.has_email === true || p2.has_email === "true") where.push("contact_email IS NOT NULL");
  const exclude = p2.exclude ?? ["applied", "ignored"];
  const excludeClauses = [];
  if (exclude.includes("applied") || exclude.includes("ignored")) {
    excludeClauses.push("id NOT IN (SELECT posting_id FROM job_votes WHERE user_id = ? AND vote IN ('applied','ignore'))");
    args.push(userId);
  }
  if (exclude.includes("seen")) {
    excludeClauses.push("id NOT IN (SELECT posting_id FROM job_votes WHERE user_id = ? AND vote = 'seen')");
    args.push(userId);
  }
  const baseWhere = [...where, ...excludeClauses].join(" AND ");
  const total = (await get(`SELECT count(*) AS n FROM job_postings WHERE ${baseWhere}`, ...args)).n;
  const nigeriaMatch = "(lower(COALESCE(location, '')) LIKE '%nigeria%' OR lower(COALESCE(location, '')) LIKE '%lagos%' OR lower(COALESCE(location, '')) LIKE '%abuja%' OR lower(COALESCE(location, '')) LIKE '%ogun%' OR lower(COALESCE(location, '')) LIKE '%ng%')";
  const orderByArgs = [];
  let orderBy;
  if (p2.sort === "recent") {
    orderBy = "posted_at DESC, created_at DESC";
  } else {
    let expr = `(COALESCE(score, 0) + CASE WHEN ${nigeriaMatch} THEN 8 ELSE 0 END)`;
    if (p2.q) {
      expr += ` + CASE WHEN lower(title) LIKE ? THEN 5 ELSE 0 END`;
      orderByArgs.push(`%${p2.q.toLowerCase()}%`);
    }
    orderBy = `${expr} DESC NULLS LAST, posted_at DESC`;
  }
  const rows = await all(
    `SELECT * FROM job_postings WHERE ${baseWhere} ORDER BY ${orderBy} LIMIT ? OFFSET ?`,
    ...args,
    ...orderByArgs,
    pageSize,
    (page - 1) * pageSize
  );
  const votes = new Map((await all("SELECT posting_id, vote FROM job_votes WHERE user_id = ?", userId)).map((r2) => [r2.posting_id, r2.vote]));
  const items = rows.map((r2) => {
    const appliedOrIgnored = ["applied", "ignore"].includes(votes.get(r2.id) ?? "");
    const fresh = scorePosting(
      signals,
      {
        title: r2.title,
        description: r2.description,
        companyName: r2.company_name,
        seniority: r2.seniority,
        remote: !!r2.remote,
        location: r2.location,
        salaryMin: r2.salary_min,
        salaryMax: r2.salary_max,
        postedAt: r2.posted_at
      },
      { appliedOrIgnored, feedbackVote: votes.get(r2.id) === "up" ? "up" : votes.get(r2.id) === "down" ? "down" : null }
    );
    return {
      id: r2.id,
      title: r2.title,
      company: { name: r2.company_name, id: r2.company_id, tier: signals.companyTiers?.[r2.company_name.toLowerCase()] ?? null },
      location: r2.location,
      remote: !!r2.remote,
      salary: r2.salary_min || r2.salary_max ? { min: r2.salary_min, max: r2.salary_max, currency: r2.currency ?? "USD" } : null,
      seniority: r2.seniority,
      source: r2.source,
      category: r2.career_category,
      contact_email: r2.contact_email ?? null,
      url: r2.url,
      posted_at: r2.posted_at,
      score: fresh.score,
      explain: fresh.explain,
      applied: votes.get(r2.id) === "applied",
      ignored: votes.get(r2.id) === "ignore",
      keywords: parseJson(r2.jd_keywords, []),
      description_snippet: (r2.description ?? "").slice(0, 320)
    };
  });
  const facetRows = await all(`SELECT source, remote, seniority, career_category FROM job_postings WHERE ${baseWhere}`, ...args);
  const facets = { source: {}, remote: {}, seniority: {}, category: {} };
  for (const r2 of facetRows) {
    facets.source[r2.source] = (facets.source[r2.source] ?? 0) + 1;
    facets.remote[String(!!r2.remote)] = (facets.remote[String(!!r2.remote)] ?? 0) + 1;
    if (r2.seniority) facets.seniority[r2.seniority] = (facets.seniority[r2.seniority] ?? 0) + 1;
    facets.category[r2.career_category] = (facets.category[r2.career_category] ?? 0) + 1;
  }
  return {
    items,
    facets,
    pagination: { page, page_size: pageSize, total_count: total, total_pages: Math.max(1, Math.ceil(total / pageSize)) },
    took_ms: Date.now() - t0,
    sources_ok: [...new Set(facetRows.map((r2) => r2.source))],
    sources_failed: []
  };
}
async function getJob(userId, id) {
  const r2 = await get("SELECT * FROM job_postings WHERE id = ? AND user_id = ?", id, userId);
  if (!r2) throw notFound("Posting");
  const signals = await profileSignals(userId);
  const fresh = scorePosting(signals, {
    title: r2.title,
    description: r2.description,
    companyName: r2.company_name,
    seniority: r2.seniority,
    remote: !!r2.remote,
    location: r2.location,
    salaryMin: r2.salary_min,
    salaryMax: r2.salary_max,
    postedAt: r2.posted_at
  });
  const vote = await get("SELECT vote FROM job_votes WHERE user_id = ? AND posting_id = ?", userId, id);
  return { ...r2, explain: fresh.explain, score: fresh.score, vote: vote?.vote ?? null, keywords: parseJson(r2.jd_keywords, []) };
}
async function voteJob(userId, id, vote) {
  const job = await get("SELECT id FROM job_postings WHERE id = ? AND user_id = ?", id, userId);
  if (!job) throw notFound("Posting");
  if (vote === "up" || vote === "down") {
    await run(
      `INSERT INTO job_votes (id, user_id, posting_id, vote, created_at) VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(user_id, posting_id) DO UPDATE SET vote = excluded.vote, created_at = excluded.created_at`,
      newId(),
      userId,
      id,
      vote,
      nowIso()
    );
  } else {
    await run("DELETE FROM job_votes WHERE user_id = ? AND posting_id = ?", userId, id);
    await run(
      `INSERT INTO job_votes (id, user_id, posting_id, vote, created_at) VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(user_id, posting_id) DO UPDATE SET vote = excluded.vote`,
      newId(),
      userId,
      id,
      vote,
      nowIso()
    );
  }
  return { ok: true, vote };
}
async function listSavedSearches(userId) {
  return all("SELECT * FROM saved_searches WHERE user_id = ? ORDER BY created_at DESC", userId);
}
async function saveSearch(userId, name2, params) {
  const id = newId();
  await run("INSERT INTO saved_searches (id, user_id, name, params, created_at) VALUES (?, ?, ?, ?, ?)", id, userId, name2, JSON.stringify(params), nowIso());
  return get("SELECT * FROM saved_searches WHERE id = ?", id);
}
async function deleteSavedSearch(userId, id) {
  const n2 = await run("DELETE FROM saved_searches WHERE id = ? AND user_id = ?", id, userId);
  if (!n2) throw notFound("Saved search");
  return { deleted: true };
}
